        lemma_map_wf_val(restrict_wf(uint_wf(7), WMInumber_cok()), WMInumber_cto(), WMInumber_cfrom(), c);
        lemma_restrict_wf_val(uint_wf(7), WMInumber_cok(), WMInumber_cfrom()(c));
