pub fn ImpactReductionContainer_jer_members(v: &ImpactReductionContainer, o: &mut String, first: &mut bool) {
    { jer_member("heightLonCarrLeft", first, o); jer_int(*&v.heightLonCarrLeft, o); }
    { jer_member("heightLonCarrRight", first, o); jer_int(*&v.heightLonCarrRight, o); }
    { jer_member("posLonCarrLeft", first, o); jer_int(*&v.posLonCarrLeft, o); }
    { jer_member("posLonCarrRight", first, o); jer_int(*&v.posLonCarrRight, o); }
    { jer_member("positionOfPillars", first, o); PositionOfPillars_jer(&v.positionOfPillars, o); }
    { jer_member("posCentMass", first, o); jer_int(*&v.posCentMass, o); }
    { jer_member("wheelBaseVehicle", first, o); jer_int(*&v.wheelBaseVehicle, o); }
    { jer_member("turningRadius", first, o); jer_int(*&v.turningRadius, o); }
    { jer_member("posFrontAx", first, o); jer_int(*&v.posFrontAx, o); }
    { jer_member("positionOfOccupants", first, o); PositionOfOccupants_bits_jer(&v.positionOfOccupants, o); }
    { jer_member("vehicleMass", first, o); jer_int(*&v.vehicleMass, o); }
    { jer_member("requestResponseIndication", first, o); RequestResponseIndication_jer(&v.requestResponseIndication, o); }
}

