#[verifier::external]
#[inline]
pub fn LocationContainer_root_jer_members(v: &LocationContainer_root, o: &mut String, first: &mut bool) {
    if let Some(x) = &v.eventSpeed { jer_member("eventSpeed", first, o); Speed_jer(x, o); }
    if let Some(x) = &v.eventPositionHeading { jer_member("eventPositionHeading", first, o); Heading_jer(x, o); }
    { jer_member("traces", first, o); Traces_jer(&v.traces, o); }
    if let Some(x) = &v.roadType { jer_member("roadType", first, o); RoadType_jer(x, o); }
}

#[verifier::external]
#[inline]
pub fn LocationContainer_root_jer(v: &LocationContainer_root, o: &mut String) {
    o.push('{');
    let mut first = true;
    LocationContainer_root_jer_members(v, o, &mut first);
    o.push('}');
}

