#[inline]
pub fn ReferenceDenms_jer(v: &ReferenceDenms, o: &mut String) { ReferenceDenms_sext_jer(v, o); }

#[verifier::external]
#[inline]
pub fn ReferenceDenms_arb(g: &mut Gen) -> ReferenceDenms { if g.bool() { ReferenceDenms_sroot_arb(g) } else { ReferenceDenms_sout_arb(g) } }

