#[verifier::external]
#[inline]
pub fn AlacarteContainer_root_jer_members(v: &AlacarteContainer_root, o: &mut String, first: &mut bool) {
    if let Some(x) = &v.lanePosition { jer_member("lanePosition", first, o); jer_int(*x, o); }
    if let Some(x) = &v.impactReduction { jer_member("impactReduction", first, o); ImpactReductionContainer_jer(x, o); }
    if let Some(x) = &v.externalTemperature { jer_member("externalTemperature", first, o); jer_int(*x, o); }
    if let Some(x) = &v.roadWorks { jer_member("roadWorks", first, o); RoadWorksContainerExtended_jer(x, o); }
    if let Some(x) = &v.positioningSolution { jer_member("positioningSolution", first, o); PositioningSolutionType_jer(x, o); }
    if let Some(x) = &v.stationaryVehicle { jer_member("stationaryVehicle", first, o); StationaryVehicleContainer_jer(x, o); }
}

