#[verifier::external]
#[inline]
pub fn DecentralizedEnvironmentalNotificationMessage_jer_members(v: &DecentralizedEnvironmentalNotificationMessage, o: &mut String, first: &mut bool) {
    { jer_member("management", first, o); ManagementContainer_jer(&v.management, o); }
    if let Some(x) = &v.situation { jer_member("situation", first, o); SituationContainer_jer(x, o); }
    if let Some(x) = &v.location { jer_member("location", first, o); LocationContainer_jer(x, o); }
    if let Some(x) = &v.alacarte { jer_member("alacarte", first, o); AlacarteContainer_jer(x, o); }
}

#[verifier::external]
#[inline]
pub fn DecentralizedEnvironmentalNotificationMessage_jer(v: &DecentralizedEnvironmentalNotificationMessage, o: &mut String) {
    o.push('{');
    let mut first = true;
    DecentralizedEnvironmentalNotificationMessage_jer_members(v, o, &mut first);
    o.push('}');
}

#[verifier::external]
#[inline]
pub fn DecentralizedEnvironmentalNotificationMessage_arb(g: &mut Gen) -> DecentralizedEnvironmentalNotificationMessage {
    DecentralizedEnvironmentalNotificationMessage {
        management: ManagementContainer_arb(g),
        situation: if g.bool() { Some(SituationContainer_arb(g)) } else { None },
        location: if g.bool() { Some(LocationContainer_arb(g)) } else { None },
        alacarte: if g.bool() { Some(AlacarteContainer_arb(g)) } else { None },
    }
}

